11	// Token is a single API token row returned by the auth-tokens endpoint.
12	// Plaintext token values are never returned by the server — only metadata.
13	type Token struct {
14		ID         string  `json:"id"`
15		UserID     string  `json:"user_id"`
16		Name       string  `json:"name"`
17		Scope      string  `json:"scope"`
18		ExpiresAt  string  `json:"expires_at"`
19		LastUsedAt *string `json:"last_used_at"`
20		CreatedAt  string  `json:"created_at"`
21	}
22	
23	// TokensResponse is the envelope returned by the list endpoint.
24	type TokensResponse struct {
25		Tokens []Token `json:"tokens"`
26	}
27	
28	// authTokensProviderVersionEnvVar must match the env var read by
29	// cmd/entire/cli/auth's currentProvider(). Duplicated here rather than
30	// imported because api/ is a leaf package and shouldn't take a
31	// dependency on auth/ for routing.
32	const authTokensProviderVersionEnvVar = "ENTIRE_AUTH_PROVIDER_VERSION" //nolint:gosec // env var name, not a credential
33	
34	// authTokensBasePath returns the auth-tokens endpoint family base path
35	// for the active provider version. v1 (default) hits /api/v1/auth/tokens;
36	// v2 hits /api/auth/tokens (no version segment).
37	func authTokensBasePath() string {
38		if strings.TrimSpace(os.Getenv(authTokensProviderVersionEnvVar)) == "v2" {
39			return "/api/auth/tokens"
40		}
41		return "/api/v1/auth/tokens"
42	}
43	
44	// ListTokens returns the authenticated user's non-expired API tokens.
45	func (c *Client) ListTokens(ctx context.Context) ([]Token, error) {
46		resp, err := c.Get(ctx, authTokensBasePath())
47		if err != nil {
48			return nil, fmt.Errorf("list tokens: %w", err)
49		}
50		defer resp.Body.Close()
51	
52		if err := CheckResponse(resp); err != nil {
53			return nil, fmt.Errorf("list tokens: %w", err)
54		}
55	
56		var out TokensResponse
57		if err := DecodeJSON(resp, &out); err != nil {
58			return nil, fmt.Errorf("list tokens: %w", err)
59		}
60		return out.Tokens, nil
61	}
62	
63	// RevokeCurrentToken revokes the bearer token used to authenticate this client.
64	func (c *Client) RevokeCurrentToken(ctx context.Context) error {
65		resp, err := c.Delete(ctx, authTokensBasePath()+"/current")
66		if err != nil {
67			return fmt.Errorf("revoke current token: %w", err)
68		}
69		defer resp.Body.Close()
70	
71		if err := CheckResponse(resp); err != nil {
72			return fmt.Errorf("revoke current token: %w", err)
73		}
74		return nil
75	}
76	
77	// RevokeToken revokes the API token with the given id.
78	func (c *Client) RevokeToken(ctx context.Context, id string) error {
79		resp, err := c.Delete(ctx, authTokensBasePath()+"/"+url.PathEscape(id))
80		if err != nil {
81			return fmt.Errorf("revoke token %s: %w", id, err)
82		}
83		defer resp.Body.Close()
84	
85		if err := CheckResponse(resp); err != nil {
86			return fmt.Errorf("revoke token %s: %w", id, err)
87		}
88		return nil
