1	package api
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"net/http"
11		"strings"
12	)
13	
14	const (
15		maxResponseBytes = 1 << 20
16		userAgent        = "entire-cli"
17	)
18	
19	// Client is an authenticated HTTP client for the Entire API.
20	// It attaches the bearer token to all outgoing requests via the Authorization header.
21	type Client struct {
22		httpClient *http.Client
23		baseURL    string
24	}
25	
26	// NewClient creates a new authenticated API client with an explicit bearer
27	// token, targeting the data API base URL (BaseURL()).
28	func NewClient(token string) *Client {
29		return NewClientWithBaseURL(token, BaseURL())
30	}
31	
32	// NewClientWithBaseURL creates a new authenticated API client targeting an
33	// explicit base URL. Use this for endpoints that live on the auth host (e.g.
34	// auth-token management) when ENTIRE_AUTH_BASE_URL splits the auth origin
35	// from the data API origin.
36	func NewClientWithBaseURL(token, baseURL string) *Client {
37		return &Client{
38			httpClient: &http.Client{
39				Transport: &bearerTransport{
40					token: token,
41					base:  http.DefaultTransport,
42				},
43			},
44			baseURL: baseURL,
45		}
46	}
47	
48	// bearerTransport is an http.RoundTripper that injects the Authorization header.
49	type bearerTransport struct {
50		token string
51		base  http.RoundTripper
52	}
53	
54	// errEmptyBearerToken surfaces at first request rather than at construction
55	// because NewClient* don't return errors. An empty bearer otherwise becomes
56	// "Authorization: Bearer " on the wire and produces a confusing 401.
57	var errEmptyBearerToken = errors.New("api: refusing to send request with empty bearer token (construct via NewAuthenticatedAPIClient)")
58	
59	func (t *bearerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
60		if t.token == "" {
61			return nil, errEmptyBearerToken
62		}
63		// Clone the request to avoid mutating the caller's request.
64		r := req.Clone(req.Context())
65		r.Header.Set("Authorization", "Bearer "+t.token)
66		r.Header.Set("User-Agent", userAgent)
67		if r.Header.Get("Accept") == "" {
68			r.Header.Set("Accept", "application/json")
69		}
70		resp, err := t.base.RoundTrip(r)
71		if err != nil {
72			return nil, fmt.Errorf("round trip: %w", err)
73		}
74		return resp, nil
75	}
76	
77	// Get sends an authenticated GET request to the given API-relative path.
78	func (c *Client) Get(ctx context.Context, path string) (*http.Response, error) {
79		return c.do(ctx, http.MethodGet, path, nil)
80	}
81	
82	// Post sends an authenticated POST request with a JSON body to the given API-relative path.
83	func (c *Client) Post(ctx context.Context, path string, body any) (*http.Response, error) {
84		var reader io.Reader
85		if body != nil {
86			data, err := json.Marshal(body)
87			if err != nil {
88				return nil, fmt.Errorf("marshal request body: %w", err)
89			}
90			reader = bytes.NewReader(data)
91		}
92		return c.do(ctx, http.MethodPost, path, reader)
93	}
94	
95	// Put sends an authenticated PUT request with a JSON body to the given API-relative path.
96	func (c *Client) Put(ctx context.Context, path string, body any) (*http.Response, error) {
97		var reader io.Reader
98		if body != nil {
99			data, err := json.Marshal(body)
100			if err != nil {
101				return nil, fmt.Errorf("marshal request body: %w", err)
102			}
103			reader = bytes.NewReader(data)
104		}
105		return c.do(ctx, http.MethodPut, path, reader)
106	}
107	
108	// Patch sends an authenticated PATCH request with a JSON body to the given API-relative path.
109	func (c *Client) Patch(ctx context.Context, path string, body any) (*http.Response, error) {
110		var reader io.Reader
111		if body != nil {
112			data, err := json.Marshal(body)
113			if err != nil {
114				return nil, fmt.Errorf("marshal request body: %w", err)
115			}
116			reader = bytes.NewReader(data)
117		}
118		return c.do(ctx, http.MethodPatch, path, reader)
119	}
120	
121	// Delete sends an authenticated DELETE request to the given API-relative path.
122	func (c *Client) Delete(ctx context.Context, path string) (*http.Response, error) {
123		return c.do(ctx, http.MethodDelete, path, nil)
124	}
125	
126	func (c *Client) do(ctx context.Context, method, path string, body io.Reader) (*http.Response, error) {
127		endpoint, err := ResolveURLFromBase(c.baseURL, path)
128		if err != nil {
129			return nil, fmt.Errorf("resolve URL %s: %w", path, err)
130		}
131	
132		req, err := http.NewRequestWithContext(ctx, method, endpoint, body)
133		if err != nil {
134			return nil, fmt.Errorf("create request: %w", err)
135		}
136	
137		if body != nil {
138			req.Header.Set("Content-Type", "application/json")
139		}
140	
141		resp, err := c.httpClient.Do(req)
142		if err != nil {
143			return nil, fmt.Errorf("%s %s: %w", method, path, err)
144		}
145		return resp, nil
146	}
147	
148	// DecodeJSON reads the response body and decodes it into dest.
149	// It limits the body size to protect against unbounded reads.
150	// The caller is responsible for closing resp.Body.
151	func DecodeJSON(resp *http.Response, dest any) error {
152		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
153		if err != nil {
154			return fmt.Errorf("read response body: %w", err)
155		}
156	
157		if err := json.Unmarshal(body, dest); err != nil {
158			return fmt.Errorf("decode JSON response: %w", err)
159		}
160	
161		return nil
162	}
163	
164	// ErrorResponse represents a standard API error response.
165	type ErrorResponse struct {
166		Error string `json:"error"`
167	}
168	
169	// HTTPError is returned by CheckResponse for non-2xx responses. Callers can use
170	// errors.As to inspect the HTTP status, or IsHTTPErrorStatus for a quick check.
171	type HTTPError struct {
172		StatusCode int
173		Message    string
174	}
175	
176	func (e *HTTPError) Error() string {
177		if e.Message != "" {
178			return fmt.Sprintf("API error: %s (status %d)", e.Message, e.StatusCode)
179		}
180		return fmt.Sprintf("API error: status %d", e.StatusCode)
181	}
182	
183	// IsHTTPErrorStatus reports whether err wraps an *HTTPError with the given HTTP status.
184	func IsHTTPErrorStatus(err error, status int) bool {
185		var ae *HTTPError
186		return errors.As(err, &ae) && ae.StatusCode == status
187	}
188	
189	// CheckResponse returns an error if the response status code indicates failure.
190	// For non-2xx responses, it reads and parses the error message from the body
191	// and returns it as an *HTTPError. The caller is responsible for closing resp.Body.
192	func CheckResponse(resp *http.Response) error {
193		if resp.StatusCode >= 200 && resp.StatusCode < 300 {
194			return nil
195		}
196	
197		apiError := &HTTPError{StatusCode: resp.StatusCode}
198	
199		body, err := io.ReadAll(io.LimitReader(resp.Body, maxResponseBytes))
200		if err != nil {
201			return apiError
202		}
203	
204		var parsed ErrorResponse
205		if err := json.Unmarshal(body, &parsed); err == nil && strings.TrimSpace(parsed.Error) != "" {
206			apiError.Message = parsed.Error
207			return apiError
208		}
209	
210		if text := strings.TrimSpace(string(body)); text != "" {
211			apiError.Message = text
212		}
213		return apiError
214	}
